#include <iostream>
#include <optional>

struct Sample
{
    double last{}, min{}, max{};
};

class Sampler
{
public:
    explicit Sampler(double perSecond) : m_interval{1.0 / perSecond} {}
    std::optional<Sample> frame(double now, double value) { return std::nullopt; }

private:
    double m_interval;
    double m_nextAt{0};
};

int main()
{
    Sampler s{10};
    int sent{0};
    for (int i{0}; i < 144; ++i)
        if (s.frame(i / 144.0, i)) ++sent;
    std::cout << sent << '\n';
}
